/**
 * Canonicalise the legacy Teaching role and move staff phone uniqueness to
 * the deterministic phoneHash generated by the PII plugin.
 */
import { decrypt, hmac } from '../utils/encryption.js';

export const description = 'Canonicalise staff roles and enforce phoneHash uniqueness';

const COLLECTION = 'staffs';
const LEGACY_PHONE_INDEX = 'schoolId_1_phone_1';
const PHONE_HASH_INDEX = 'schoolId_1_phoneHash_1';

async function collectionExists(db) {
  return (await db.listCollections({ name: COLLECTION }).toArray()).length > 0;
}

async function dropIfPresent(collection, indexName) {
  const indexes = await collection.indexes();
  if (indexes.some((index) => index.name === indexName)) await collection.dropIndex(indexName);
}

export async function up(db, { dryRun }) {
  if (!(await collectionExists(db))) {
    console.log(`    [SKIP] ${COLLECTION}: collection does not exist`);
    return;
  }

  const collection = db.collection(COLLECTION);
  const legacyRoleCount = await collection.countDocuments({ role: 'Teaching' });
  const phoneRows = await collection
    .find(
      { isDeleted: { $ne: true }, phone: { $type: 'string' } },
      { projection: { schoolId: 1, phone: 1, phoneHash: 1 } }
    )
    .toArray();
  const repairs = [];
  const seenHashes = new Set();
  const duplicateHashes = new Set();
  for (const row of phoneRows) {
    const phoneHash = row.phoneHash || hmac(decrypt(row.phone));
    if (!phoneHash) continue;
    const tenantHash = `${row.schoolId}:${phoneHash}`;
    if (seenHashes.has(tenantHash)) duplicateHashes.add(tenantHash);
    seenHashes.add(tenantHash);
    if (!row.phoneHash) repairs.push({ _id: row._id, phoneHash });
  }

  console.log(`    [SCAN] ${legacyRoleCount} staff role document(s) require canonicalisation.`);
  console.log(`    [SCAN] ${repairs.length} staff phone hash(es) require backfill.`);
  if (duplicateHashes.size > 0) {
    throw new Error(
      `Active staff contain ${duplicateHashes.size} duplicate phone hash group(s); resolve them before applying the unique index.`
    );
  }
  if (dryRun) return;

  await collection.updateMany(
    { role: 'Teaching' },
    { $set: { 'role.$[legacyRole]': 'Teacher' } },
    { arrayFilters: [{ legacyRole: 'Teaching' }] }
  );
  if (repairs.length > 0) {
    await collection.bulkWrite(
      repairs.map((repair) => ({
        updateOne: {
          filter: { _id: repair._id },
          update: { $set: { phoneHash: repair.phoneHash } },
        },
      }))
    );
  }
  await dropIfPresent(collection, LEGACY_PHONE_INDEX);
  await collection.createIndex(
    { schoolId: 1, phoneHash: 1 },
    {
      name: PHONE_HASH_INDEX,
      unique: true,
      partialFilterExpression: { phoneHash: { $type: 'string' }, isDeleted: false },
    }
  );
}

export async function down(db, { dryRun }) {
  if (!(await collectionExists(db))) return;
  console.log('    Restoring the legacy encrypted-phone index; canonical roles are retained.');
  if (dryRun) return;

  const collection = db.collection(COLLECTION);
  await dropIfPresent(collection, PHONE_HASH_INDEX);
  await collection.createIndex(
    { schoolId: 1, phone: 1 },
    {
      name: LEGACY_PHONE_INDEX,
      unique: true,
      partialFilterExpression: { phone: { $type: 'string' }, isDeleted: false },
    }
  );
}
